// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: from address and value v and a boolean to choose empty vs non-empty _tos
    function testFuzz_property(address from, uint256 v, bool makeEmpty) public {
        // keep from non-zero to be a sensible caller (but allow zero as admissible too)
        // v can be any uint256; do not constrain v to exclude zero because the mutant changes behavior around zero/non-zero
        // prepare _tos according to the boolean: empty array or one-element array
        address[] memory tos;
        if (makeEmpty) {
            tos = new address[](0);
        } else {
            tos = new address[](1);
            tos[0] = address(0xBEEF);
        }

        // call transfer and observe whether it returns (ok=true) or reverts (ok=false)
        bool ok;
        try c.transfer(from, address(0xCAFE), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference implementation always reverts (ok==false) when _tos.length == 0.
        // We assert that whenever we passed an empty _tos, the call did NOT succeed.
        // The mutant that replaced the check with require(v>0) will allow success for empty _tos when v>0,
        // so this assertion will fail on that mutant for some fuzz inputs.
        if (makeEmpty) {
            assertTrue(!ok);
        } else {
            // for non-empty tos the reference can succeed (and typically does if callee calls succeed),
            // but we do not require any particular outcome here — only the empty-tos rule is universal.
            assertTrue(true);
        }
    }
}
